const assert=require('node:assert/strict');
module.exports=async page=>{
 const initial=await page.evaluate(()=>({instance,selected,sends:window.sent.length}));
 await page.locator('#connections-open').click();
 await page.waitForSelector('#connections-list .connection-item');
 assert.equal(await page.locator('#connections-list .connection-item').count(),5);
 const records=await page.evaluate(async()=>{const r=await fetch(new URL('api/connections',root));return (await r.json()).items;});
 const sshRecord=records.find(r=>r.instance===initial.instance&&r.session==='s1');
 const ssh=page.locator(`#connections-list [data-key="${sshRecord.key}"]`);
 await ssh.click();await page.waitForSelector('#connection-show-passwords');
 assert.equal(await page.locator('#connection-show-passwords').isChecked(),false);
 assert.equal(await page.locator('.connection-password').first().innerText(),'••••••••');
 await page.locator('#connection-show-passwords').check();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='secret');
 await page.locator('#connection-show-passwords').uncheck();
 assert.equal(await page.locator('.connection-password').first().innerText(),'••••••••');
 await page.locator('#connections-list [data-host="archive.example"]').click();
 await page.waitForFunction(()=>document.getElementById('connection-detail').textContent.includes('archive.example'));
 assert.equal(await page.locator('#connection-show-passwords').isChecked(),false);
 await page.locator('#connection-show-passwords').check();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='archived-current-secret'&&document.querySelector('.connection-password-history')?.textContent.includes('archived-secret'));
 await page.locator('#connections-list [data-protocol="telnet"][data-username=""]').click();
 await page.waitForSelector('#connection-credentials-form');
 assert.equal(await page.locator('#connection-show-passwords').isChecked(),false);
 assert.equal(await page.locator('.connection-password').first().innerText(),'未记录');
 await page.locator('#connection-username').fill('人工用户名');
 await page.locator('#connection-password-edit').fill('manual-browser-secret');
 await page.locator('#connection-credentials-form button').click();
 await page.waitForFunction(()=>document.getElementById('connection-detail').textContent.includes('人工填写，未验证')&&!document.querySelector('#connection-credentials-form button')?.disabled);
 await page.locator('#connection-show-passwords').check();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='manual-browser-secret');
 // Saving an unchanged password preserves it, without pre-filling the edit field.
 assert.equal(await page.locator('#connection-password-edit').inputValue(),'');
 await page.locator('#connection-username').fill('改名');
 await page.locator('#connection-credentials-form button').click();
 await page.waitForFunction(()=>document.getElementById('connections-status').textContent.includes('资料已保存')&&document.getElementById('connection-username')?.value==='改名'&&!document.getElementById('connection-show-passwords').checked&&!document.querySelector('#connection-credentials-form button')?.disabled);
 await page.locator('#connection-show-passwords').check();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='manual-browser-secret');
 // Rotate the same account's password; old values are available only while revealed.
 await page.locator('#connection-password-edit').fill('rotated-browser-secret');
 await page.locator('#connection-credentials-form button').click();
 await page.waitForFunction(()=>!!document.querySelector('#connection-credentials-form button')&&!document.querySelector('#connection-credentials-form button').disabled&&document.getElementById('connection-show-passwords')?.checked===false);
 await page.locator('#connection-show-passwords').check();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='rotated-browser-secret'&&document.querySelector('.connection-password-history')?.textContent.includes('manual-browser-secret'));
 assert(!/\bs[0-9]+\b/.test(await page.locator('#connection-detail h3').innerText()),'session IDs must not be displayed as connection titles');
 await page.locator('#connection-show-passwords').uncheck();
 assert.equal(await page.locator('.connection-password-history').first().innerText(),'');
 await page.locator('#connections-close').click();
 assert.equal(await page.locator('#connection-detail').innerText(),'');
 assert.deepEqual(await page.evaluate(()=>({instance,selected,sends:window.sent.length})),initial);
 assert.equal(await page.evaluate(()=>JSON.stringify(localStorage).includes('browser-secret')),false);
 await page.locator('#connections-open').click();await page.waitForSelector('#connections-list .connection-item');
 await page.locator('#connections-list [data-protocol="telnet"][data-username="改名"]').click();await page.waitForSelector('#connection-credentials-form');
 assert.equal(await page.locator('#connection-show-passwords').isChecked(),false);
 await page.locator('#connection-password-clear').check();await page.locator('#connection-credentials-form button').click();
 await page.waitForFunction(()=>document.querySelector('.connection-password')?.textContent==='未记录');
 await page.keyboard.press('Escape');
 assert.equal(await page.locator('#connection-detail').innerText(),'');
};
